import XCTest
final class BskyAutomationTests: XCTestCase {
  func testTapOpenThenFeeds() {
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    let open = springboard.alerts.buttons["Open"]
    if open.waitForExistence(timeout: 3) { open.tap() }

    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    app.activate()
    let feeds = app.staticTexts.matching(NSPredicate(format: "label CONTAINS[c] 'Feeds'")).firstMatch
    if feeds.waitForExistence(timeout: 8) {
      feeds.tap()
    } else {
      app.coordinate(withNormalizedOffset: CGVector(dx: 0.60, dy: 0.22)).tap()
    }
  }
}
EOF

